def calculate_S(N):
    """Calculates S(N) = sum_{a=1}^N sum_{b=1}^N floor(ab / (N+1))."""
    N_plus_1 = N + 1
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // N_plus_1
    return S

def calculate_R(N):
    """Calculates R(N) = sum_{a=1}^N sum_{b=1}^N (ab mod (N+1))."""
    N_plus_1 = N + 1
    R = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            R += (a * b) % N_plus_1
    return R

# Test N=3, N=7, N=11
tests = [3, 7, 11]
results = {}

for N in tests:
    S_N = calculate_S(N)
    R_N = calculate_R(N)

    # Target values
    T_N = (N**3 - N**2 + 2) / 4
    R_target_N = (N + 1)**2 * (N - 1) / 2

